// W5 (part c), section 3 for welltest: pick A on the beginner tier (the OBODO-4
// buildup, a file opened in the buildup explorer's Your test mode) and pick B
// on intermediate and advanced (panel defaults off the capstone settings; keys
// unchanged; no lesson prints a graded value).
//
//   KEYS. The committed buildup file is exactly what the case module builds
//   through the engine's own buildup superposition, and the six keys are
//   regenerated by parsing it and running the panel lab (buildupWindowFor,
//   over the vendored Horner analysis). They equal the spec and the migration.
//   LEAKS. No panel source, the page or any welltest lesson carries a graded
//   value in any string shape or a decimal inside a precise graded tolerance;
//   every panel's opening state lands on no graded value.
//   LABEL. The W1 open-book label and lesson notes are gone.
//   CONTROLS. Every check goes red on a planted leak.
import { describe, it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import {
  REPO, renderingsOf, leaksIn, nearValuesIn, lessonsOf, sourcesOf, migrationFields, W1_LABEL, W1_LESSON_NOTE, TIERS,
} from '@/lib/w5cGuardKit';
import * as L from './welltestLab';
import { build, gradedKeys, RESERVOIR, TP, MIN_DT } from '../../../../../docs/graded-field-audit/w5c/welltest/case.mjs';

const SPEC = JSON.parse(fs.readFileSync(path.join(REPO, 'docs/graded-field-audit/w5c/welltest.json'), 'utf8'));
const FIELDS = JSON.parse(fs.readFileSync(path.join(REPO, 'docs/graded-field-audit/w5c/welltest/fields.json'), 'utf8'));
const CSV = path.join(REPO, 'src/content/capstone-cases/welltest/obodo4_buildup.csv');
const MIG = '20261028c_w5_welltest.sql';
const LIVE = Object.fromEntries(TIERS.map((t) => [t, migrationFields(MIG, 'welltest', t)]));
const ALL = TIERS.flatMap((t) => LIVE[t].fields.map((f) => ({ ...f, tier: t })));

const PANEL_DIR = 'src/components/course/panels/welltest';
const PAGE = 'src/pages/apps/WellTestLearningPage.jsx';
const SOURCES = sourcesOf(PANEL_DIR, [PAGE]);
const LESSONS = lessonsOf('welltest');
const RENDER = ALL.filter((f) => !Number.isInteger(f.expected)).flatMap((f) => renderingsOf(f.key, f.expected));

describe('W5c welltest: the OBODO-4 buildup and its keys', () => {
  it('commits exactly the buildup file the case module builds through the engine', () => {
    expect(fs.readFileSync(CSV, 'utf8')).toBe(build().text);
    expect(L.parseBuildupText(build().text)).toHaveLength(40);
  });

  it('regenerates the six keys from the committed file through the engine; they equal the spec and the migration', () => {
    const { n, ...keys } = gradedKeys(fs.readFileSync(CSV, 'utf8'), build().pwfShutIn);
    expect(n).toBe(10);
    expect(keys.beginner).toEqual(FIELDS.beginner);
    expect(LIVE.beginner.fields.map((f) => [f.key, f.expected, f.tol])).toEqual(FIELDS.beginner.map((f) => [f.key, f.expected, f.tol]));
    expect(LIVE.beginner.prompt).toBe(SPEC.tiers.beginner.prompt);
    // every constant the learner types is in the brief
    for (const v of [RESERVOIR.q, TP, build().pwfShutIn, RESERVOIR.phi, RESERVOIR.mu, RESERVOIR.rw, RESERVOIR.h, RESERVOIR.B, MIN_DT]) {
      expect(LIVE.beginner.prompt, String(v)).toContain(String(v));
    }
  });

  it('every tier drops the W1 label; the stripped tiers keep their keys and the engine still gives them', () => {
    for (const t of TIERS) expect(LIVE[t].prompt, t).not.toMatch(W1_LABEL);
    const cv = L.capstoneValues();
    const v = (t, k) => LIVE[t].fields.find((f) => f.key === k).expected;
    const pick = (obj, k) => (obj && typeof obj === 'object' ? obj[k] : undefined);
    for (const t of ['intermediate', 'advanced']) {
      for (const f of LIVE[t].fields) {
        const got = pick(cv[t], f.key);
        if (got !== undefined) expect(Math.abs(got - f.expected), `${t}/${f.key}`).toBeLessThan(1e-9 * Math.max(1, Math.abs(f.expected)));
      }
    }
    expect(Math.abs(L.plateauMean('buildup', { from: 5 }) - v('intermediate', 'radial_plateau_psi'))).toBeLessThan(1e-9);
  });
});

describe('W5c welltest: nothing prints a graded answer before the learner works', () => {
  it('sweeps real sources and lessons', () => {
    expect(SOURCES.map((s) => s.file)).toEqual([
      `${PANEL_DIR}/BuildupExplorer.jsx`, `${PANEL_DIR}/DiagnosticExplorer.jsx`, `${PANEL_DIR}/RegressionExplorer.jsx`,
      `${PANEL_DIR}/welltestLab.js`, PAGE,
    ]);
    expect(LESSONS.length).toBeGreaterThan(60);
    expect(ALL).toHaveLength(18);
    expect(RENDER.length).toBeGreaterThan(40);
  });

  it('no source or lesson carries a graded value in any shape, or a decimal inside a precise graded tolerance', () => {
    const hits = [];
    for (const s of [...SOURCES, ...LESSONS]) for (const h of leaksIn(s.text, RENDER)) hits.push(`${s.file}: ${h.key} as ${h.text} (${h.shape})`);
    for (const l of LESSONS) for (const h of nearValuesIn(l.text, ALL)) hits.push(`${l.file}: ${h.text} within tol of ${h.key}`);
    expect(hits).toEqual([]);
  });

  it('every panel and the page header, at their opening settings, land on no graded value', () => {
    const seen = openingStateNumbers();
    expect(seen.length).toBeGreaterThan(30);
    const hits = [];
    for (const f of ALL) for (const x of seen) if (Math.abs(x.v - f.expected) <= f.tol) hits.push(`${f.tier}/${f.key} ~ ${x.what} ${x.v}`);
    expect(hits).toEqual([]);
  });

  it('the W1 open-book lesson note is gone from every welltest tier', () => {
    expect(LESSONS.filter((l) => W1_LESSON_NOTE.test(l.text)).map((l) => l.file)).toEqual([]);
  });
});

describe('W5c welltest: negative controls', () => {
  it('a graded value planted at full float, nine digits or four decimals is caught', () => {
    const missed = [];
    for (const f of ALL.filter((x) => !Number.isInteger(x.expected))) {
      const r = RENDER.filter((x) => x.key === f.key);
      if (!r.length) continue;
      for (const shown of [String(f.expected), f.expected.toPrecision(9), f.expected.toFixed(4)]) {
        if (shown.replace('-', '').length < 6 || !shown.includes('.')) continue;
        if (!leaksIn(`x = ${shown}`, r).length) missed.push(`${f.key}: ${shown}`);
      }
    }
    expect(missed).toEqual([]);
  });

  it('the old opening states are caught: the diagnostic explorer on the buildup, the page header to one decimal', () => {
    const plateau = ALL.find((x) => x.key === 'radial_plateau_psi');
    const faultK = ALL.find((x) => x.key === 'fault_late_k_md');
    const planted = [...openingStateNumbers(),
      { what: 'diagnostic on buildup', v: L.plateauMean('buildup', { from: 5 }) },
      { what: 'header to 1 dp', v: Number(L.faultLines().late.k.toFixed(1)) }];
    expect(planted.some((x) => Math.abs(x.v - plateau.expected) <= plateau.tol)).toBe(true);
    expect(planted.some((x) => Math.abs(x.v - faultK.expected) <= faultK.tol)).toBe(true);
  });
});

// Every number the buildup explorer (teaching mode, window at or after 5 h,
// and its window walk), the diagnostic explorer (drawdown) and the page
// header show before any input.
function openingStateNumbers() {
  const out = [];
  const add = (what, v) => { if (Number.isFinite(v)) out.push({ what, v }); };
  const bw = L.buildupWindow(5);
  for (const k of ['k', 'skin', 'm', 'pStar', 'p1hr', 'dpSkin', 'riAtTp', 'flowEfficiency', 'r2', 'kErrorPct', 'skinError']) add(`buildup ${k}`, bw[k]);
  for (const w of L.windowWalk()) { add(`walk ${w.minDt} k`, w.k); add(`walk ${w.minDt} skin`, w.skin); add(`walk ${w.minDt} r2`, w.r2); }
  const truth = L.fixtureTruth('drawdown');
  add('diagnostic drawdown late plateau', L.plateauMean('drawdown', { from: 200 }));
  add('diagnostic drawdown plateau at planted k', L.theoreticalPlateau(truth.k));
  // the page header
  const wide = L.buildupWindow(0);
  add('header wide k', Number(wide.k.toFixed(2))); add('header wide skin', Number(wide.skin.toFixed(2)));
  add('header fault late k', Number(L.faultLines().late.k.toFixed(0)));
  add('header naive multirate k', Number(L.multiRateCase().naive.k.toFixed(0)));
  return out;
}
